}

.tencel-logo {
    flex: 0 0 165px;
    text-align: center;
}

.tencel-logo img {
    width: 152px;
    max-width: 100%;
    height: auto;
}

.tencel-content {
    flex: 1;
    min-width: 0;
}

.tencel-content h3 {
    margin: 0 0 8px 0;
}

.tencel-row {
    display: flex;
    margin-bottom: 4px;
}

.tencel-count {
    flex: 0 0 28px;
}

@media only screen and (max-width: 600px) {
    .tencel-box {
        display: block;
    }

    .tencel-logo {
        text-align: left;
        margin-bottom: 15px;
    }

    .tencel-content h3 {
        margin-top: 0;
    }

    .tencel-row {
        display: grid;
        grid-template-columns: 28px 1fr;
    }
}




